const std = @import("std");
pub const br = @import("../br.zig");
pub const core = @import("../core.zig");
pub const allocator = std.testing.allocator;
pub const Counter = core.StreamCount;
pub const pattern = "ABCDEFGHIJKLMNOP";

/// Generated by an independent git archive of dacd500a10e68a9dcbd93ab46a301fcbdc4a3e91.
/// Baseline archive SHA-256 b84e2ca115771b95b7ca24eeda2a8cb6baf55cf925e00184533e8accb6470d48.
/// The oracle generated each wire and decoded it using only that archive.
pub const Golden = struct { label: []const u8, wire_hex: []const u8, payload: []const u8 };
pub const goldens = [_]Golden{
    .{ .label = "stored-metadata", .wire_hex = "ac05636f756e7465722d6d6574617800084142434445464748494a4b4c4d4e4f507800084142434445464748494a4b4c4d4e4f507800084142434445464748494a4b4c4d4e4f5003", .payload = pattern ** 3 },
    .{ .label = "literal-metadata-stored", .wire_hex = "40000000345a19db9b402100a9ad05636f756e7465722d6d6574617800084142434445464748494a4b4c4d4e4f507800084142434445464748494a4b4c4d4e4f507800084142434445464748494a4b4c4d4e4f5003", .payload = "hello" ++ pattern ** 3 },
    .{ .label = "copy-repcodes", .wire_hex = "200000044458210248410a4700000888b0420490821400", .payload = "aaaaa" },
    .{ .label = "rle-257", .wire_hex = "02200004845e2c16101d", .payload = "z" ** 257 },
    .{ .label = "incremental-stored", .wire_hex = "f000104142434445464748494a4b4c4d4e4f507800084142434445464748494a4b4c4d4e4f507800084142434445464748494a4b4c4d4e4f5003", .payload = pattern ** 3 },
    .{ .label = "incremental-planned", .wire_hex = "f000104142434445464748494a4b4c4d4e4f507800001e022084898ff000003c044008131f0d", .payload = pattern ** 3 },
    .{ .label = "incremental-static-dictionary", .wire_hex = "f000003c044001134cbd725a7a1f000f00c043801430c8d40d4717b4b11e0300e02100c290c8fd25", .payload = "compression compression compression " },
};

pub fn goldenAlloc(golden: Golden) ![]u8 {
    const wire = try allocator.alloc(u8, golden.wire_hex.len / 2);
    errdefer allocator.free(wire);
    _ = try std.fmt.hexToBytes(wire, golden.wire_hex);
    return wire;
}

pub fn decodeSplit(decoder: anytype, wire: []const u8, expected: []const u8) !void {
    const output = try allocator.alloc(u8, expected.len);
    defer allocator.free(output);
    var read: usize = 0;
    var written: usize = 0;
    while (decoder.snapshot().phase != .done) {
        const result = try decoder.step(wire[read..@min(wire.len, read + 1)], output[written..@min(output.len, written + 3)]);
        read += result.progress.input_read;
        written += result.progress.output_written;
        try std.testing.expect(result.progress.input_read != 0 or result.progress.output_written != 0 or result.status == .done);
    }
    try decoder.finish();
    try std.testing.expectEqual(wire.len, read);
    try std.testing.expectEqual(expected.len, written);
    try std.testing.expectEqualSlices(u8, expected, output);
}

pub fn encode(encoder: anytype, payload: []const u8) ![]u8 {
    var wire: std.ArrayList(u8) = .empty;
    errdefer wire.deinit(allocator);
    var output: [3]u8 = undefined;
    var offset: usize = 0;
    while (offset < payload.len) {
        const result = try encoder.step(payload[offset..@min(payload.len, offset + 7)], &output);
        offset += result.progress.input_read;
        try wire.appendSlice(allocator, output[0..result.progress.output_written]);
        try std.testing.expect(result.progress.input_read != 0 or result.progress.output_written != 0);
    }
    try encoder.finish();
    while (true) {
        const result = try encoder.step("", &output);
        try wire.appendSlice(allocator, output[0..result.progress.output_written]);
        if (result.status == .done) break;
        try std.testing.expect(result.progress.output_written != 0);
    }
    return wire.toOwnedSlice(allocator);
}

/// Independent arithmetic model for a repeated, byte-aligned stored block.
/// The first block and every following block carry a three-byte header; direct
/// payload bytes do not advance the progressive compressed-bit cursor.
pub const StoredPrefix = struct {
    blocks: u128,
    input_bytes: u128,
    output_bytes: u128,
    consumed_header_bits: u128,

    pub fn init(blocks: u128) StoredPrefix {
        return .{ .blocks = blocks, .input_bytes = blocks * (pattern.len + 3), .output_bytes = blocks * pattern.len, .consumed_header_bits = blocks * 24 };
    }
};

/// Install the exact trailing ring contents of the virtual repeated prefix.
/// Its absolute positions determine both pattern bytes and physical slots;
/// using a non-power-of-two ring exercises the Counter-to-local-index boundary.
pub fn fillRing(history: []u8, total_output: u128, bytes: []const u8) void {
    const retained: usize = @intCast(@min(total_output, history.len));
    for (0..retained) |i| {
        const absolute = total_output - retained + i;
        history[@intCast(absolute % history.len)] = bytes[@intCast(absolute % bytes.len)];
    }
}

/// Equivalent state after N complete stored blocks in one valid stream. First
/// decode the archived first block, then summarize whole identical blocks.
/// These are model fixtures, not evidence that N blocks were actually decoded.
pub fn copyStoredPrefix(decoder: *br.IncrementalCopyStreamDecoder, blocks: Counter) !StoredPrefix {
    try std.testing.expect(blocks != 0);
    const wire = try goldenAlloc(goldens[4]);
    defer allocator.free(wire);
    var output: [pattern.len]u8 = undefined;
    const result = try decoder.step(wire[0 .. pattern.len + 3], &output);
    try std.testing.expectEqualSlices(u8, pattern, &output);
    try std.testing.expectEqual(@as(usize, pattern.len + 3), result.progress.input_read);
    try std.testing.expectEqual(.trailer, decoder.phase);
    try std.testing.expectEqual(@as(u8, 0), decoder.staged_bit_count);
    try std.testing.expectEqual(@as(usize, 24), decoder.stream_bits);
    return applyCopyStoredPrefix(decoder, blocks);
}

fn applyCopyStoredPrefix(decoder: *br.IncrementalCopyStreamDecoder, blocks: Counter) StoredPrefix {
    const model = StoredPrefix.init(blocks);
    decoder.total_input = @intCast(model.input_bytes);
    decoder.total_output = @intCast(model.output_bytes);
    decoder.stream_bits = @truncate(model.consumed_header_bits);
    fillRing(decoder.history, model.output_bytes, pattern);
    decoder.previous = .{ pattern[pattern.len - 2], pattern[pattern.len - 1] };
    return model;
}

pub fn ownedStoredPrefix(decoder: *br.IncrementalStreamDecoder, blocks: Counter) !StoredPrefix {
    const wire = try goldenAlloc(goldens[4]);
    defer allocator.free(wire);
    var output: [pattern.len]u8 = undefined;
    const result = try decoder.step(wire[0 .. pattern.len + 3], &output);
    try std.testing.expectEqualSlices(u8, pattern, &output);
    try std.testing.expectEqual(@as(usize, pattern.len + 3), result.progress.input_read);
    try std.testing.expectEqual(.trailer, decoder.progressive.?.phase);
    const model = applyCopyStoredPrefix(&decoder.progressive.?, blocks);
    decoder.frame_input_read = @intCast(model.input_bytes);
    decoder.frame_output_written = @intCast(model.output_bytes);
    return model;
}

/// Window 16, one non-final 16-byte metadata block, ending on a byte boundary.
/// The following block has no repeated window prefix. Bytes are an independent
/// RFC bit-field construction: ISLAST=0, MNIBBLES=3, reserved=0, MSKIPBYTES=1,
/// MSKIPLEN=15, followed by zero alignment padding.
pub const first_metadata = [_]u8{ 0xac, 0x07 } ++ pattern.*;
pub const next_metadata = [_]u8{ 0xd6, 0x03 } ++ pattern.*;

pub const MetadataPrefix = struct {
    blocks: u128,
    input_bytes: u128,
    metadata_bytes: u128,
    consumed_header_bits: u128,
    pub fn init(blocks: u128) MetadataPrefix {
        return .{ .blocks = blocks, .input_bytes = blocks * first_metadata.len, .metadata_bytes = blocks * pattern.len, .consumed_header_bits = blocks * 16 };
    }
};

pub fn metadataPrefix(decoder: anytype, blocks: Counter) !MetadataPrefix {
    try std.testing.expect(blocks != 0);
    const result = try decoder.step(&first_metadata, &.{});
    try std.testing.expectEqual(first_metadata.len, result.progress.input_read);
    try std.testing.expectEqual(@as(usize, 0), result.progress.output_written);
    try std.testing.expectEqual(@as(@TypeOf(decoder.metadata_total), pattern.len), decoder.metadata_total);
    try std.testing.expectEqual(@as(@TypeOf(decoder.metadata_block_count), 1), decoder.metadata_block_count);
    return applyMetadataPrefix(decoder, blocks);
}

fn applyMetadataPrefix(decoder: anytype, blocks: Counter) !MetadataPrefix {
    const model = MetadataPrefix.init(blocks);
    decoder.total_input = @intCast(model.input_bytes);
    decoder.metadata_total = @intCast(model.metadata_bytes);
    decoder.metadata_block_count = @intCast(model.blocks);
    const capture: usize = @intCast(@min(model.metadata_bytes, decoder.metadata_output.len));
    for (decoder.metadata_output[0..capture], 0..) |*byte, i| byte.* = pattern[i % pattern.len];
    decoder.metadata_written = capture;
    const lengths: usize = @intCast(@min(model.blocks, decoder.metadata_block_lengths.len));
    @memset(decoder.metadata_block_lengths[0..lengths], pattern.len);
    if (@hasField(@TypeOf(decoder.*), "stream_bits")) {
        try std.testing.expectEqual(@as(usize, 16), decoder.stream_bits);
        decoder.stream_bits = @truncate(model.consumed_header_bits);
    }
    return model;
}

pub fn ownedMetadataPrefix(decoder: *br.IncrementalStreamDecoder, blocks: Counter) !MetadataPrefix {
    const result = try decoder.step(&first_metadata, &.{});
    try std.testing.expectEqual(first_metadata.len, result.progress.input_read);
    try std.testing.expectEqual(@as(usize, 0), result.progress.output_written);
    const model = try applyMetadataPrefix(&decoder.progressive.?, blocks);
    decoder.frame_input_read = @intCast(model.input_bytes);
    return model;
}

pub fn nextStoredBlock() ![]u8 {
    const wire = try goldenAlloc(goldens[4]);
    defer allocator.free(wire);
    return allocator.dupe(u8, wire[pattern.len + 3 .. (pattern.len + 3) * 2]);
}

pub fn literalStoredPrefix(decoder: *br.IncrementalLiteralStreamDecoder, blocks: Counter) !StoredPrefix {
    const wire = try goldenAlloc(goldens[1]);
    defer allocator.free(wire);
    // Archived compressed hello, captured metadata, then one complete stored
    // block. The next two stored blocks and final-empty marker remain omitted.
    const prefix_len = wire.len - 1 - (pattern.len + 3) * 2;
    var output: [5 + pattern.len]u8 = undefined;
    const result = try decoder.step(wire[0..prefix_len], &output);
    try std.testing.expectEqual(prefix_len, result.progress.input_read);
    try std.testing.expectEqualSlices(u8, "hello" ++ pattern, &output);
    try std.testing.expectEqual(.trailer, decoder.phase);
    try std.testing.expectEqual(@as(usize, 0), decoder.stream_bits % 8);
    try std.testing.expectEqual(@as(usize, 144), decoder.stream_bits);
    try std.testing.expectEqual(@as(u8, 0), decoder.staged_bit_count);
    const repeats: u128 = @as(u128, blocks) - 1;
    const model: StoredPrefix = .{
        .blocks = blocks,
        .input_bytes = @as(u128, prefix_len) + repeats * (pattern.len + 3),
        .output_bytes = @as(u128, output.len) + repeats * pattern.len,
        .consumed_header_bits = @as(u128, decoder.stream_bits) + repeats * 24,
    };
    decoder.total_input = @intCast(model.input_bytes);
    decoder.total_output = @intCast(model.output_bytes);
    decoder.stream_bits = @truncate(model.consumed_header_bits);
    return model;
}

pub fn closedOwnedPrefix(decoder: *br.IncrementalStreamDecoder, frames: Counter, wire: []const u8, payload: []const u8) !void {
    try std.testing.expect(frames != 0);
    try decodeSplit(decoder, wire, payload);
    const input: u128 = @as(u128, frames) * wire.len;
    const output: u128 = @as(u128, frames) * payload.len;
    try std.testing.expect(input <= std.math.maxInt(Counter) and output <= std.math.maxInt(Counter));
    decoder.total_compressed = @intCast(input);
    decoder.total_output = @intCast(output);
    decoder.frame_count = frames;
}

pub fn closedEncoderPrefix(encoder: anytype, frames: Counter, wire_len: usize, payload_len: usize) !void {
    try std.testing.expect(encoder.done and frames != 0);
    try std.testing.expectEqual(@as(Counter, @intCast(payload_len)), encoder.total_input);
    try std.testing.expectEqual(@as(Counter, @intCast(wire_len)), encoder.total_output);
    const input: u128 = @as(u128, frames) * payload_len;
    const output: u128 = @as(u128, frames) * wire_len;
    try std.testing.expect(input <= std.math.maxInt(Counter) and output <= std.math.maxInt(Counter));
    // Complete identical streams reset every codec's frame-local history and
    // models. Its retained state is the actual final stream parsed above;
    // operation counts and completed-stream count summarize the earlier ones.
    encoder.stream_input = @intCast(input);
    encoder.stream_output = @intCast(output);
    encoder.stream_count = @intCast(frames);
}

pub fn expectErrorProgress(decoder: anytype, input: usize, output: usize) !void {
    const diagnostic = decoder.diagnostics();
    const progress = diagnostic.last_step_progress orelse return error.TestUnexpectedResult;
    try std.testing.expectEqual(input, progress.input_read);
    try std.testing.expectEqual(output, progress.output_written);
}
